observation.command:
cd /tmp/probe && cat > probe.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>disable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
    <AssemblyName>probe</AssemblyName>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="Program.cs" />
  </ItemGroup>
  <ItemGroup>
    <PackageReference Include="Microsoft.Extensions.Configuration" Version="8.0.0" />
    <PackageReference Include="Microsoft.Extensions.Configuration.Json" Version="8.0.0" />
    <PackageReference Include="Microsoft.Extensions.Configuration.EnvironmentVariables" Version="8.0.0" />
    <PackageReference Include="Microsoft.Extensions.Configuration.Binder" Version="8.0.0" />
  </ItemGroup>
</Project>
EOF
cat > Program.cs <<'EOF'
using System;
using System.Reflection;
using Microsoft.Extensions.Configuration;

class Probe {
  static void Main(string[] args) {
    var appBin = "/workspace/src/Bovis.Web/bin/Debug/net8.0/";
    var config = new ConfigurationBuilder()
        .AddJsonFile(appBin + "appsettings.json", false, true)
        .AddJsonFile(appBin + "appsettings.Development.json", false, true)
        .AddJsonFile(appBin + "local.json", false, true)
        .AddEnvironmentVariables()
        .Build();

    // Force-load Bovis.Web.dll (loads deps too via LoadFrom context)
    var asm = Assembly.LoadFrom(appBin + "Bovis.Web.dll");
    var ifas = Assembly.LoadFrom(appBin + "Bovis.Interfaces.dll");
    var binderType = ifas.GetType("Bovis.Interfaces.Configuration.ConfigurableBinder", throwOnError: true);
    binderType.GetConstructor(new Type[]{ typeof(IConfiguration) }).Invoke(new object[]{ config });
    var globals = asm.GetType("Bovis.Web.Globals", throwOnError: true);
    string boundCookie = (string)globals.GetField("AuthCookie", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string boundPub = (string)globals.GetField("PublicBaseUrl", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);

    Console.WriteLine("CONFIG[Bovis.Web:AuthCookie]     = " + config["Bovis.Web:AuthCookie"]);
    Console.WriteLine("CONFIG[Bovis.Web:PublicBaseUrl]  = " + config["Bovis.Web:PublicBaseUrl"]);
    Console.WriteLine("BOUND Globals.AuthCookie         = " + boundCookie);
    Console.WriteLine("BOUND Globals.PublicBaseUrl      = " + boundPub);
    Console.WriteLine("COOKIE_MATCH(appsettings==bound) = " + (boundCookie == config["Bovis.Web:AuthCookie"]));
  }
}
EOF
rm -rf bin obj && dotnet build -v q -nologo 2>&1 | tail -3 && ASPNETCORE_ENVIRONMENT=Development dotnet bin/Debug/net8.0/probe.dll 2>&1 | tail -6
